// PM search terms for the Bundesagentur Jobsuche API (P2-03).
// 'Produktmanagerin' returns the same jobs as 'Produktmanager', so it is left out.
const terms = ['Product Manager', 'Produktmanager', 'Product Owner', 'Head of Product'];
return terms.map(was => ({ json: { was } }));

// One item per unique job (by referenznummer) across all search terms.
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  for (const job of item.json.ergebnisliste || []) {
    const ref = job.referenznummer;
    if (!ref || seen.has(ref)) continue;
    seen.add(ref);
    out.push({ json: { ...job, detailsKey: Buffer.from(ref).toString('base64') } });
  }
}
return out;

// Map each Bundesagentur job to JobPilot's common job shape.
const MAX_DESC = 6000; // characters sent on to scoring
const list = $('Flatten + de-duplicate').all();
return $input.all().map((item, i) => {
  const s = list[i].json;            // search result (always there)
  const d = item.json || {};         // details (may be an error)
  const loc = (s.stellenlokationen || []).map(l => l.adresse?.ort).filter(Boolean);
  const desc = (d.stellenangebotsBeschreibung || '').replace(/\*\*/g, '').replace(/\n{3,}/g, '\n\n').trim();
  const salary = s.gehaltsspanneVon ? `${s.gehaltsspanneVon}–${s.gehaltsspanneBis || ''} (${s.artDerVerguetung || ''})` : null;
  return { json: {
    id: `ba:${s.referenznummer}`,
    source: 'bundesagentur',
    market: 'DE',
    title: (s.stellenangebotsTitel || '').trim(),
    company: s.firma || null,
    location: [...new Set(loc)].join(', ') || null,
    remote: s.homeofficemoeglich ? (s.homeofficetyp || 'possible') : 'no',
    published: s.datumErsteVeroeffentlichung || null,
    salary,
    description: desc.slice(0, MAX_DESC),
    description_missing: !desc,
    link: `https://www.arbeitsagentur.de/jobsuche/jobdetail/${s.referenznummer}`,
    external_link: s.externeURL || null,
  } };
});

// PM title phrases for Adzuna, London (P2-04). Matched in the job title only.
// One page of 50 per phrase: the largest phrase returned 16 jobs a day. Add page 2 if a count nears 50.
const phrases = ['product manager', 'product owner', 'head of product'];
return phrases.map(title_only => ({ json: { title_only, page: 1 } }));

// One item per unique Adzuna job, in JobPilot's common job shape.
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  for (const j of item.json.results || []) {
    if (!j.id || seen.has(j.id)) continue;
    seen.add(j.id);
    const salary = j.salary_min && !Number(j.salary_is_predicted)
      ? `£${Math.round(j.salary_min)}–${j.salary_max ? Math.round(j.salary_max) : ''}` : null;
    out.push({ json: {
      id: `adzuna:${j.id}`,
      source: 'adzuna',
      market: 'UK',
      title: (j.title || '').replace(/<[^>]+>/g, '').trim(),
      company: j.company?.display_name || null,
      location: j.location?.display_name || null,
      remote: /remote|hybrid/i.test(`${j.title} ${j.description}`) ? 'mentioned' : 'not mentioned',
      published: (j.created || '').slice(0, 10) || null,
      salary,
      description: (j.description || '').replace(/<[^>]+>/g, '').trim(), // Adzuna gives a snippet only
      description_missing: !j.description,
      link: j.redirect_url,
      external_link: null,
      attribution: 'Adzuna',
    } });
  }
}
return out;
